import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim()); // 读入 n
        long[] a = new long[n+1], s = new long[n+1];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for(int i = 1; i <= n; i++){
            a[i] = Long.parseLong(st.nextToken());      // 读入 a[i]
            s[i] = s[i-1] + a[i];                       // 构造前缀和
        }

        // 存放最大乘积，用于防溢出用 long double 模拟 __int128
        long maxv = 0;
        // 枚举 y
        for(int y = 2; y < n; y++){
            long T = s[y];  // 前两段总和
            // 二分查找最接近 T/2 的位置
            int l = 1, r = y;
            while(l < r){
                int mid = (l + r) >>> 1;
                if(s[mid] < T/2.0) l = mid + 1;
                else r = mid;
            }
            // 检查 l 和 l-1
            for(int d = -1; d <= 0; d++){
                int x = l + d;
                if(x >= 1 && x < y){
                    long v = s[x] * (T - s[x]) * (s[n] - T);
                    if(v > maxv) maxv = v;
                }
            }
        }
        // 输出结果
        System.out.println(maxv % MOD);
    }
}
